head.script:
scwin.onpageload = function() {};
scwin.onpageunload = function() {};
scwin.test = function(e) {
    var contentWidth = 800;
    var contentH = 600;
    var bodyWidth = 1280;
    var bodyH = 800;
    var scalePoint = contentWidth / bodyWidth;
    var scalePointH = contentH / bodyH;
    var scaleP = scalePoint <= scalePointH ? scalePoint : scalePointH;
    var scale = 'scale(' + (scaleP) + ')';
    var contentHeight = $('html').height();
    var bodyHeight = contentHeight / scalePoint;
    var bottomPoint = bodyHeight - contentHeight;
    $('body').css({
        'position': 'absolute',
        'top': '0',
        'width': '1280px',
        'height': 'initial',
        '-ms-transform': scale,
        'transform': scale,
        'transform-origin': 'top left'
    });
}
scwin.check1 = function() {
    return Math.abs(((j) => j.length ? j : $('#mf_sldTest1_thumb1'))($('#sldTest1_thumb1')).position().left - ((j) => j.length ? j : $('#mf_sldTest1_scale_1_1'))($('#sldTest1_scale_1_1')).position().left) < 10 ? true : false;
}
scwin.check2 = function() {
    return Math.abs(((j) => j.length ? j : $('#mf_sldTest1_thumb1'))($('#sldTest1_thumb1')).position().left - ((j) => j.length ? j : $('#mf_sldTest1_scale_end_1'))($('#sldTest1_scale_end_1')).position().left) < 10 ? true : false;
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
}
